179: $paramsObjectBound = $PSBoundParameters.ContainsKey('ParamsObject')
180: if ($paramsObjectBound -and ($PSBoundParameters.ContainsKey('Params') -or $PSBoundParameters.ContainsKey('ParamsPath'))) {
181:     throw '-ParamsObject cannot be combined with -Params or -ParamsPath.'
182: }
183: 
184: $paramsFromObject = ''
185: if ($paramsObjectBound) {
186:     . (Join-Path $pluginRootFull 'lib\yaml-object-mutation.ps1')
187:     Import-McpYamlSerializer
188:     $paramsFromObject = ConvertTo-Yaml -Data $ParamsObject -Options WithIndentedSequences
189: }
190: 
191: switch ($Command) {
192:     'Status' {
193:         Invoke-PowerShellPluginScript -ScriptPath (Join-Path $pluginRootFull 'lib\mcp-status.ps1')
194:     }
195:     'Invoke' {
196:         if (-not $Method) {
197:             throw '-Method is required when -Command Invoke is used.'
198:         }
199: 
200:         $paramsText = if ($paramsObjectBound) {
201:             $paramsFromObject
202:         } else {
203:             Read-OptionalText -Inline $Params -HasInline:$($PSBoundParameters.ContainsKey('Params')) -Path $ParamsPath
204:         }
205: 
206:         # Params travel in a file, never on the child command line (32,767-character limit on Windows).
207:         . (Join-Path $pluginRootFull 'lib\repl-params-transfer.ps1')
208:         $paramsTransfer = New-McpReplParamsTransfer -ParamsText ($paramsText ?? '')
209:         try {
210:             Invoke-PowerShellPluginScript -ScriptPath (Join-Path $pluginRootFull 'lib\repl-invoke.ps1') -Arguments (@('-Method', $Method) + @($paramsTransfer.Arguments))
211:         }
212:         finally {
213:             Remove-McpReplParamsTransfer -Transfer $paramsTransfer
214:         }
215:     }
216:     'CompleteTurn' {
217:         $responseText = Read-OptionalText -Inline $Response -HasInline:$($PSBoundParameters.ContainsKey('Response')) -Path $ResponsePath
218:         if (-not $responseText) {
219:             $responseText = 'Turn completed.'
220:         }
221: 
222:         Invoke-PowerShellPluginScript -ScriptPath (Join-Path $pluginRootFull 'lib\final-response.ps1') -StandardInput $responseText
223:     }
224: }
