1: #Requires -Version 7.0
2: <#
3: .SYNOPSIS
4:     Read-only: lists every environment variable name that C# sources under the given roots read or set through a
5:     string literal (Environment.GetEnvironmentVariable / SetEnvironmentVariable / ExpandEnvironmentVariables tokens,
6:     and nameof-free literal constants passed to them), with the files that use each name and whether the use is a
7:     read or a write. Used to choose the variables a hostile-environment Test run scripts.
8: .PARAMETER Roots
9:     Semicolon-separated directories to scan.
10: #>
11: [CmdletBinding()]
12: param(
13:     [Parameter(Mandatory)] [string] $Roots
14: )
15: 
16: Set-StrictMode -Version Latest
17: $ErrorActionPreference = 'Stop'
18: 
19: Write-Output "Now: $((Get-Date).ToString('s')) roots=$Roots"
20: $pattern = [regex]'(?<op>GetEnvironmentVariable|SetEnvironmentVariable)\s*\(\s*"(?<name>[A-Za-z_][A-Za-z0-9_]*)"'
21: $uses = [System.Collections.Generic.Dictionary[string, System.Collections.Generic.SortedSet[string]]]::new()
22: foreach ($root in @($Roots -split ';' | Where-Object { $_ })) {
23:     foreach ($file in Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.cs' | Where-Object { $_.FullName -notmatch '[\\/](bin|obj)[\\/]' }) {
24:         $text = [System.IO.File]::ReadAllText($file.FullName)
25:         foreach ($m in $pattern.Matches($text)) {
26:             $key = $m.Groups['name'].Value
27:             if (-not $uses.ContainsKey($key)) { $uses[$key] = [System.Collections.Generic.SortedSet[string]]::new() }
28:             $op = if ($m.Groups['op'].Value -eq 'SetEnvironmentVariable') { 'set' } else { 'get' }
29:             $relative = [System.IO.Path]::GetRelativePath($root, $file.FullName).Replace('\', '/')
30:             [void]$uses[$key].Add("$op $([System.IO.Path]::GetFileName($root))/$relative")
31:         }
32:     }
33: }
34: foreach ($key in ($uses.Keys | Sort-Object)) {
35:     $entries = @($uses[$key])
36:     $sets = @($entries | Where-Object { $_ -like 'set *' }).Count
37:     $gets = @($entries | Where-Object { $_ -like 'get *' }).Count
38:     Write-Output ('{0} files: get={1} set={2}' -f $key, $gets, $sets)
39:     foreach ($e in $entries | Select-Object -First 6) { Write-Output "    $e" }
40:     if ($entries.Count -gt 6) { Write-Output "    ... $($entries.Count - 6) more" }
41: }
42: Write-Output "names=$($uses.Count)"
43: 
