3: /// <summary>
4: /// TR-MCP-WS-005 / AC-TR-MCP-WS-005-001, TR-MCP-SESSIONLOG-006 / AC-TR-MCP-SESSIONLOG-006-009:
5: /// walks a directory tree under the user profile breadth first without following directory links or other
6: /// reparse points, and skips the contents of any directory whose listing fails with an IO or access error
7: /// (an untrusted mount point, an access-denied or vanished folder), so a scan never fails on what it cannot
8: /// traverse.
9: /// </summary>
10: /// <remarks>
11: /// A directory is yielded when its parent lists it, unless it is a link; its contents are walked only when its own
12: /// listing succeeds. File links are yielded as files. Listing errors other than <see cref="IOException"/> and
13: /// <see cref="UnauthorizedAccessException"/> propagate.
14: /// </remarks>
15: internal sealed class DirectoryTreeWalker
16: {
17:     private static readonly EnumerationOptions s_singleLevel = new()
18:     {
19:         RecurseSubdirectories = false,
20:         IgnoreInaccessible = false,
21:         AttributesToSkip = 0,
22:         ReturnSpecialDirectories = false,
23:     };
24: 
25:     private readonly Func<string, IReadOnlyList<DirectoryListingEntry>> _list;
26: 
27:     /// <summary>Creates a walker that lists each directory through <paramref name="list"/>.</summary>
28:     /// <param name="list">Lists one directory, or throws when it cannot be listed.</param>
29:     internal DirectoryTreeWalker(Func<string, IReadOnlyList<DirectoryListingEntry>> list)
30:     {
31:         ArgumentNullException.ThrowIfNull(list);
32:         _list = list;
33:     }
34: 
35:     /// <summary>The walker over the real file system.</summary>
36:     internal static DirectoryTreeWalker FileSystem { get; } = new(ListFileSystem);
37: 
38:     /// <summary>Every directory below <paramref name="root"/> that the walk reaches.</summary>
39:     /// <param name="root">Directory to walk; it is listed but not yielded.</param>
40:     /// <returns>The reached directories, breadth first.</returns>
41:     internal IEnumerable<string> EnumerateDirectories(string root) => Walk(root, yieldDirectories: true);
42: 
43:     /// <summary>Every file below <paramref name="root"/> that the walk reaches.</summary>
44:     /// <param name="root">Directory to walk.</param>
45:     /// <returns>The reached files, breadth first.</returns>
46:     internal IEnumerable<string> EnumerateFiles(string root) => Walk(root, yieldDirectories: false);
47: 
48:     /// <summary>Lists one real directory with each entry's directory and link flags.</summary>
49:     /// <param name="directory">Directory to list.</param>
50:     /// <returns>The entries of <paramref name="directory"/>.</returns>
51:     internal static IReadOnlyList<DirectoryListingEntry> ListFileSystem(string directory) =>
52:         new DirectoryInfo(directory)
53:             .EnumerateFileSystemInfos("*", s_singleLevel)
54:             .Select(info => new DirectoryListingEntry(
55:                 info.FullName,
56:                 info is DirectoryInfo,
57:                 (info.Attributes & FileAttributes.ReparsePoint) != 0))
58:             .ToList();
59: 
60:     private IEnumerable<string> Walk(string root, bool yieldDirectories)
61:     {
62:         var pending = new Queue<string>();
63:         pending.Enqueue(root);
64:         while (pending.Count > 0)
65:         {
66:             foreach (var entry in TryList(pending.Dequeue()))
67:             {
68:                 if (entry.IsDirectory)
69:                 {
70:                     if (entry.IsLink)
71:                         continue;
72:                     pending.Enqueue(entry.Path);
73:                     if (yieldDirectories)
74:                         yield return entry.Path;
75:                 }
76:                 else if (!yieldDirectories)
77:                 {
78:                     yield return entry.Path;
79:                 }
80:             }
81:         }
82:     }
83: 
84:     private IReadOnlyList<DirectoryListingEntry> TryList(string directory)
85:     {
86:         try
87:         {
88:             return _list(directory);
89:         }
90:         catch (IOException)
91:         {
92:             return [];
93:         }
94:         catch (UnauthorizedAccessException)
95:         {
96:             return [];
97:         }
98:     }
99: }
