4: namespace QBrainAi.Support.Mcp.Services;
5: 
6: /// <summary>
7: /// FR-MCP-SESSIONLOGCTX-001 / AC-FR-MCP-SESSIONLOGCTX-001-006 / AC-TR-MCP-SESSIONLOG-006-003:
8: /// Extracts planFile and todoId from turn contents and agent history under ~.
9: /// </summary>
10: public sealed class SessionLogTurnContextExtractor
11: {
12:     private static readonly Regex PathToken = new(
13:         @"(?:~[/\\]|[A-Za-z]:[/\\]|[/\\]|(?<![\w./\\-]))(?:[\w.-]+[/\\])+[\w.-]+\.[A-Za-z0-9]+",
14:         RegexOptions.Compiled | RegexOptions.CultureInvariant);
15: 
16:     private static readonly Regex TodoToken = new(
17:         @"\b(?:[A-Z]+-[A-Z0-9]+-\d{3}|ISSUE-\d+)\b",
18:         RegexOptions.Compiled | RegexOptions.CultureInvariant);
19: 
20:     private const int MaxHistoryFiles = 20;
21:     private const int MaxHistoryBytes = 1_048_576;
22: 
23:     private readonly DirectoryTreeWalker _walker;
24: 
25:     /// <summary>
26:     /// Creates an extractor whose agent-history scan walks the real file system (AC-TR-MCP-SESSIONLOG-006-009).
27:     /// </summary>
28:     public SessionLogTurnContextExtractor()
29:         : this(DirectoryTreeWalker.FileSystem)
30:     {
31:     }
32: 
33:     /// <summary>
34:     /// AC-TR-MCP-SESSIONLOG-006-009: creates an extractor whose agent-history scan walks through
35:     /// <paramref name="walker"/>, which skips directory links and any directory it cannot list.
36:     /// </summary>
37:     /// <param name="walker">Directory walk used for the history scan.</param>
38:     internal SessionLogTurnContextExtractor(DirectoryTreeWalker walker)
39:     {
40:         ArgumentNullException.ThrowIfNull(walker);
41:         _walker = walker;
42:     }
43: 
44:     /// <summary>
45:     /// Extracts a validated pair. Always returns <see cref="SessionLogTurnContextValidator.NoneSentinel"/>
46:     /// or a valid value. Never invents ids or paths.
47:     /// </summary>
48:     /// <param name="turn">Turn entity with children loaded.</param>
49:     /// <param name="workspacePath">Active workspace path for relative matching.</param>
50:     /// <param name="userProfilePath">Fake or real user profile used as ~.</param>
51:     /// <param name="agentSessionId">Optional session AgentSessionId for history matching.</param>
52:     /// <param name="agentSessionTranscriptFile">Optional exact transcript path.</param>
53:     /// <returns>Normalized planFile and todoId.</returns>
54:     public (string PlanFile, string TodoId) Extract(
55:         SessionLogTurnEntity turn,
56:         string? workspacePath,
57:         string? userProfilePath = null,
58:         string? agentSessionId = null,
59:         string? agentSessionTranscriptFile = null)
60:     {
61:         ArgumentNullException.ThrowIfNull(turn);
62: 
63:         var sources = CollectSources(turn, workspacePath, userProfilePath, agentSessionId, agentSessionTranscriptFile, _walker);
64:         var todoId = ExtractTodoId(turn, sources);
65:         var planFile = ExtractPlanFile(turn, sources, workspacePath, userProfilePath);
66:         return (planFile, todoId);
67:     }
68: 
69:     private static List<string> CollectSources(
70:         SessionLogTurnEntity turn,
71:         string? workspacePath,
72:         string? userProfilePath,
73:         string? agentSessionId,
74:         string? agentSessionTranscriptFile,
75:         DirectoryTreeWalker walker)
76:     {
77:         var parts = new List<string>();
78:         AddIfAny(parts, turn.QueryTitle);
79:         AddIfAny(parts, turn.QueryText);
80:         AddIfAny(parts, turn.Response);
81:         AddIfAny(parts, turn.Interpretation);
82:         foreach (var tag in turn.Tags)
83:             AddIfAny(parts, tag.Tag);
84:         foreach (var context in turn.ContextItems)
85:             AddIfAny(parts, context.ContextItem);
86:         foreach (var item in turn.StringListItems)
87:             AddIfAny(parts, item.Value);
88:         foreach (var action in turn.Actions)
89:         {
90:             AddIfAny(parts, action.FilePath);
91:             AddIfAny(parts, action.Description);
92:         }
93: 
94:         foreach (var dialog in turn.ProcessingDialog)
95:             AddIfAny(parts, dialog.Content);
96: 
97:         AppendHistory(parts, workspacePath, userProfilePath, agentSessionId, agentSessionTranscriptFile, walker);
98:         return parts;
99:     }
100: 
101:     private static void AppendHistory(
102:         List<string> parts,
103:         string? workspacePath,
104:         string? userProfilePath,
105:         string? agentSessionId,
106:         string? agentSessionTranscriptFile,
107:         DirectoryTreeWalker walker)
108:     {
109:         var files = new List<string>();
110:         if (!string.IsNullOrWhiteSpace(agentSessionTranscriptFile) && File.Exists(agentSessionTranscriptFile))
111:             files.Add(agentSessionTranscriptFile);
112: 
113:         var home = userProfilePath
114:             ?? Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
115:         if (string.IsNullOrWhiteSpace(home) || !Directory.Exists(home))
116:             return;
117: 
118:         var workspaceSlug = string.IsNullOrWhiteSpace(workspacePath)
119:             ? null
120:             : Path.GetFileName(workspacePath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
121: 
122:         foreach (var rootName in new[] { ".grok", ".claude", ".codex", ".cursor" })
123:         {
124:             var root = Path.Combine(home, rootName);
125:             if (!Directory.Exists(root))
126:                 continue;
127: 
128:             // AC-TR-MCP-SESSIONLOG-006-009: the walk skips directory links and any directory it cannot list.
129:             foreach (var file in walker.EnumerateFiles(root))
130:             {
131:                 if (files.Count >= MaxHistoryFiles)
132:                     break;
133:                 if (HistoryFileMatches(file, agentSessionId, workspaceSlug))
134:                     files.Add(file);
135:             }
136:         }
137: 
138:         if (!string.IsNullOrWhiteSpace(workspacePath))
139:         {
140:             var map = Path.Combine(workspacePath, ".mcpServer", "plan-todo-map.yaml");
141:             if (File.Exists(map))
142:                 files.Add(map);
143:         }
144: 
145:         foreach (var file in files.Distinct(StringComparer.OrdinalIgnoreCase).Take(MaxHistoryFiles))
146:         {
147:             try
148:             {
149:                 var info = new FileInfo(file);
150:                 if (!info.Exists || info.Length == 0)
151:                     continue;
152:                 using var stream = info.OpenRead();
153:                 var buffer = new byte[Math.Min(MaxHistoryBytes, info.Length)];
154:                 var read = stream.Read(buffer, 0, buffer.Length);
155:                 parts.Add(System.Text.Encoding.UTF8.GetString(buffer, 0, read));
156:             }
157:             catch (IOException)
158:             {
159:                 // Skip unreadable history files.
160:             }
161:             catch (UnauthorizedAccessException)
162:             {
163:                 // Skip locked history files.
164:             }
165:         }
166:     }
167: 
168:     private static bool HistoryFileMatches(string file, string? agentSessionId, string? workspaceSlug)
169:     {
170:         if (!string.IsNullOrWhiteSpace(agentSessionId)
171:             && ContainsPathSegment(file, agentSessionId))
172:             return true;
173:         if (!string.IsNullOrWhiteSpace(workspaceSlug)
174:             && workspaceSlug.Length >= 4
175:             && ContainsPathSegment(file, workspaceSlug))
176:             return true;
177:         return false;
178:     }
179: 
180:     private static bool ContainsPathSegment(string path, string segment)
181:     {
182:         var normalized = path.Replace('\\', '/');
183:         var needle = segment.Replace('\\', '/');
184:         var index = 0;
185:         while ((index = normalized.IndexOf(needle, index, StringComparison.OrdinalIgnoreCase)) >= 0)
186:         {
187:             var beforeOk = index == 0 || IsPathSeparator(normalized[index - 1]);
188:             var afterIndex = index + needle.Length;
189:             var afterOk = afterIndex >= normalized.Length || IsPathSeparator(normalized[afterIndex]);
190:             if (beforeOk && afterOk)
191:                 return true;
192:             index = afterIndex;
193:         }
194: 
195:         return false;
196:     }
197: 
198:     private static bool IsPathSeparator(char ch) => ch is '/' or '\\' or '%' or ':' or '.';
199: 
200:     private static string ExtractTodoId(SessionLogTurnEntity turn, IReadOnlyList<string> sources)
201:     {
202:         var tagHits = turn.Tags
203:             .Select(t => t.Tag)
204:             .Where(tag => tag is not null && IsTodoId(tag))
205:             .Distinct(StringComparer.Ordinal)
206:             .ToList();
207:         if (tagHits.Count == 1)
208:             return tagHits[0]!;
209:         if (tagHits.Count > 1)
210:             return SessionLogTurnContextValidator.NoneSentinel;
211: 
212:         var counts = new Dictionary<string, int>(StringComparer.Ordinal);
213:         foreach (var source in sources)
214:         {
215:             foreach (Match match in TodoToken.Matches(source))
216:             {
217:                 var value = match.Value;
218:                 if (!IsTodoId(value) || IsEmbeddedInRequirementId(source, match.Index))
219:                     continue;
220:                 counts[value] = counts.GetValueOrDefault(value) + 1;
221:             }
222:         }
223: 
224:         if (counts.Count == 0)
225:             return SessionLogTurnContextValidator.NoneSentinel;
226:         var max = counts.Values.Max();
227:         var winners = counts.Where(pair => pair.Value == max).Select(pair => pair.Key).ToList();
228:         return winners.Count == 1 ? winners[0] : SessionLogTurnContextValidator.NoneSentinel;
229:     }
230: 
231:     private static bool IsTodoId(string value)
232:     {
233:         if (SessionLogTurnContextValidator.RequirementId.IsMatch(value))
234:             return false;
235:         return SessionLogTurnContextValidator.CanonicalTodoId.IsMatch(value)
236:             || SessionLogTurnContextValidator.IssueTodoId.IsMatch(value);
237:     }
238: 
239:     private static bool IsEmbeddedInRequirementId(string source, int index)
240:     {
241:         if (index >= 5 && source.AsSpan(index - 5, 5).Equals("TEST-", StringComparison.Ordinal))
242:             return true;
243:         if (index >= 3)
244:         {
245:             var prefix = source.AsSpan(index - 3, 3);
246:             if (prefix.Equals("TR-", StringComparison.Ordinal) || prefix.Equals("FR-", StringComparison.Ordinal))
247:                 return true;
248:         }
249: 
250:         return false;
251:     }
252: 
253:     private static string ExtractPlanFile(
254:         SessionLogTurnEntity turn,
255:         IReadOnlyList<string> sources,
256:         string? workspacePath,
257:         string? userProfilePath)
258:     {
259:         var candidates = new List<string>();
260:         foreach (var context in turn.ContextItems)
261:             AddCandidate(candidates, context.ContextItem, userProfilePath);
262:         foreach (var item in turn.StringListItems.Where(i => i.ListType == "FileModified"))
263:             AddCandidate(candidates, item.Value, userProfilePath);
264:         foreach (var action in turn.Actions)
265:             AddCandidate(candidates, action.FilePath, userProfilePath);
266: 
267:         foreach (var source in sources)
268:         {
269:             foreach (Match match in PathToken.Matches(source))
270:                 AddCandidate(candidates, match.Value.Trim().Trim('"', '\''), userProfilePath);
271:         }
272: 
273:         var unique = candidates.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
274:         if (unique.Count == 0)
275:             return SessionLogTurnContextValidator.NoneSentinel;
276: 
277:         var docsPlans = unique.Where(p => p.Contains("/docs/plans/", StringComparison.OrdinalIgnoreCase)).ToList();
278:         if (docsPlans.Count == 1)
279:             return docsPlans[0];
280: 
281:         var homePlans = unique.Where(LooksLikePlanFile).ToList();
282:         if (homePlans.Count == 1)
283:             return homePlans[0];
284: 
285:         var namedPlan = unique.Where(p => Path.GetFileName(p).Contains("plan", StringComparison.OrdinalIgnoreCase)).ToList();
286:         if (namedPlan.Count == 1)
287:             return namedPlan[0];
288: 
289:         return unique.Count == 1 ? unique[0] : SessionLogTurnContextValidator.NoneSentinel;
290:     }
291: 
292:     private static bool LooksLikePlanFile(string path)
293:     {
294:         var file = Path.GetFileName(path);
295:         return file.Contains("plan", StringComparison.OrdinalIgnoreCase)
296:             || path.Contains("/docs/plans/", StringComparison.OrdinalIgnoreCase)
297:             || path.Contains("/plans/", StringComparison.OrdinalIgnoreCase);
298:     }
299: 
300:     private static void AddCandidate(List<string> candidates, string? raw, string? userProfilePath)
301:     {
302:         if (string.IsNullOrWhiteSpace(raw))
303:             return;
304:         try
305:         {
306:             var normalized = SessionLogTurnContextValidator.NormalizePlanFile(raw, userProfilePath);
307:             if (normalized != SessionLogTurnContextValidator.NoneSentinel)
308:                 candidates.Add(normalized);
309:         }
310:         catch (ArgumentException)
311:         {
312:             // Drop invalid path tokens.
313:         }
314:     }
315: 
316:     private static void AddIfAny(List<string> parts, string? value)
317:     {
318:         if (!string.IsNullOrWhiteSpace(value))
319:             parts.Add(value);
320:     }
321: }
