5: namespace QBrainAi.Support.Mcp.Tests.Services;
6: 
7: /// <summary>
8: /// Production binding of the directory-walk cases to the two user-profile scans: marker agent-plugin version
9: /// resolution and the session-log agent-history scan each keep working when a directory under the profile is an
10: /// untrusted mount point (its listing throws) or a link, and neither scan fails.
11: /// </summary>
12: /// <remarks>
13: /// Requirement coverage: TR-MCP-WS-005 / AC-TR-MCP-WS-005-001 and TR-MCP-SESSIONLOG-006 /
14: /// AC-TR-MCP-SESSIONLOG-006-009 (operator 2026-10-20: "Fix scans in PR 87 (Recommended)"; triage report
15: /// b0e41c36). Test data: a temporary profile the test creates, listed through
16: /// <see cref="DirectoryTreeWalker.ListFileSystem"/>, with the failure conditions scripted on top: one directory's
17: /// listing throws the untrusted-mount-point <see cref="IOException"/> seen on PAYTON-LEGION2 as kingd, and one
18: /// directory is reported as a link. Seam controls run the same profile with the link flag removed and prove the
19: /// result changes, so the expected values come from the link and error handling rather than from the layout. The
20: /// version-file cases (operator 2026-10-20: "Fold R3-P3 in first") read the same profile through
21: /// <see cref="MarkerFileService.ReadExistingFileText"/> with named <c>.version</c> files scripted to throw the
22: /// sharing-violation <see cref="IOException"/> of a locked file; their seam control reads every file normally.
23: /// </remarks>
24: public sealed class UserProfileScanBindingTests : IDisposable
25: {
26:     private const string UntrustedMountPointMessage =
27:         "The path cannot be traversed because it contains an untrusted mount point.";
28: 
29:     private const string PluginName = "mcpserver-scan-binding-plugin";
30: 
31:     private readonly string _root = Path.Combine(Path.GetTempPath(), $"mcp-scan-binding-{Guid.NewGuid():N}");
32: 
33:     /// <summary>Creates the temporary root that holds the profile and the workspace.</summary>
34:     public UserProfileScanBindingTests() => Directory.CreateDirectory(_root);
35: 
36:     /// <summary>Deletes the temporary root.</summary>
37:     public void Dispose()
38:     {
39:         if (Directory.Exists(_root))
40:             Directory.Delete(_root, recursive: true);
41:     }
42: 
43:     private string Profile => Path.Combine(_root, "profile");
44: 
45:     private string Workspace => Path.Combine(_root, "workspace");
46: 
47:     private static bool SamePath(string left, string right) =>
48:         string.Equals(Path.GetFullPath(left), Path.GetFullPath(right), StringComparison.Ordinal);
49: 
50:     /// <summary>
51:     /// A walker over the real temporary profile in which <paramref name="unlistable"/> throws the untrusted-mount-point
52:     /// error and <paramref name="link"/> (when given) is reported as a directory link.
53:     /// </summary>
54:     private static DirectoryTreeWalker ScriptedWalker(string unlistable, string? link) =>
55:         new(directory =>
56:         {
57:             if (SamePath(directory, unlistable))
58:                 throw new IOException(UntrustedMountPointMessage);
59:             return DirectoryTreeWalker.ListFileSystem(directory)
60:                 .Select(entry => link is not null && SamePath(entry.Path, link) ? entry with { IsLink = true } : entry)
61:                 .ToList();
62:         });
63: 
64:     private (string Unlistable, string Linked) CreatePluginCacheProfile()
65:     {
66:         var cache = Path.Combine(Profile, ".claude", "plugins", "cache");
67:         var reachable = Path.Combine(cache, PluginName, "7.7.7");
68:         var linked = Path.Combine(cache, PluginName, "9.9.9");
69:         var unlistable = Path.Combine(cache, "caveman");
