1: <# .SYNOPSIS Runs independent full Nuke unit gates under ordinary and scripted hostile environments. #>
2: [CmdletBinding(SupportsShouldProcess)]
3: param([ValidateSet('Sandbox','Hostile')][string]$Kind='Sandbox')
4: $ErrorActionPreference='Stop'
5: $runId='hv-ug-r5-' + $Kind.ToLowerInvariant() + '-test-1'
6: if (-not $PSCmdlet.ShouldProcess((Get-Location).Path, ('Run full Nuke Test ' + $runId))) { return }
7: $started=Get-Date
8: $root=Join-Path '/tmp' $runId
9: if (Test-Path -LiteralPath $root) { throw 'Fresh reviewer run root already exists.' }
10: [void][IO.Directory]::CreateDirectory($root)
11: $environmentChanges=[ordered]@{NUGET_HTTP_CACHE_PATH=(Join-Path $root 'nuget-http'); MCP_NUKE_POWERSHELL_BOOTSTRAPPED='1'}
12: if ($Kind -eq 'Hostile') {
13:     $original=Get-Content -Raw -LiteralPath 'docs/receipts/unit-suite-green-20261019/ug-r5-hostile-wide-4.meta.json' | ConvertFrom-Json -AsHashtable
14:     foreach ($entry in $original.environment.GetEnumerator()) {
15:         $value=([string]$entry.Value).Replace($original.hostileRoot,$root)
16:         if ($value -eq '[REDACTED:api-key]') { $value='hostile-scripted-not-a-key' }
17:         $environmentChanges[$entry.Key]=$value
18:         if ($value.StartsWith($root, [StringComparison]::Ordinal)) { [void][IO.Directory]::CreateDirectory($value) }
19:     }
20:     foreach ($directory in $original.manifestDirs) {
21:         $path=([string]$directory).Replace($original.hostileRoot,$root)
22:         [void][IO.Directory]::CreateDirectory($path)
23:         ConvertTo-Json -InputObject @() | Set-Content -LiteralPath (Join-Path $path 'plugin.json')
24:     }
25:     $historyPath=([string]$original.historyFile).Replace($original.hostileRoot,$root)
26:     [void][IO.Directory]::CreateDirectory((Split-Path -Parent $historyPath))
27:     [ordered]@{sessionId='HOSTILE-REVIEW-001';text='PLAN-HOSTILE-001 and TODO HOSTILE-ENV-001'} | ConvertTo-Json -Compress | Set-Content -LiteralPath $historyPath
28: }
29: $meta=[ordered]@{RunId=$runId;Target='Test';Head=(& git rev-parse HEAD);DirtyPaths=@(& git status --short);StartLocal=$started.ToString('s');StartUtc=$started.ToUniversalTime().ToString('o');Environment=$environmentChanges;Command='pwsh.exe -NoProfile -NonInteractive -File ./build.ps1 Test --test-run-id ' + $runId}
30: $outPath=Join-Path $PSScriptRoot ($runId+'.out.txt')
31: $errPath=Join-Path $PSScriptRoot ($runId+'.err.txt')
32: $psi=[Diagnostics.ProcessStartInfo]::new()
33: $psi.FileName=(Get-Command pwsh.exe).Source
34: $psi.WorkingDirectory=(Get-Location).Path
35: $psi.UseShellExecute=$false
36: $psi.RedirectStandardOutput=$true
37: $psi.RedirectStandardError=$true
38: foreach ($argument in @('-NoProfile','-NonInteractive','-File','./build.ps1','Test','--test-run-id',$runId)) { $psi.ArgumentList.Add($argument) }
39: foreach ($entry in $environmentChanges.GetEnumerator()) { $psi.Environment[$entry.Key]=[string]$entry.Value }
40: $process=[Diagnostics.Process]::Start($psi)
41: $stdout=$process.StandardOutput.ReadToEndAsync()
42: $stderr=$process.StandardError.ReadToEndAsync()
43: $process.WaitForExit()
44: [IO.File]::WriteAllText($outPath,$stdout.GetAwaiter().GetResult())
45: [IO.File]::WriteAllText($errPath,$stderr.GetAwaiter().GetResult())
46: $meta.ExitCode=$process.ExitCode
47: $meta.EndLocal=Get-Date -Format s
48: $meta.OutputPath=$outPath
49: $serialized=$meta | ConvertTo-Json -Depth 8
50: $serialized=[regex]::Replace($serialized,'(?i)(API_KEY"\s*:\s*")[^"]{20,}', '$1[REDACTED:api-key]')
51: [IO.File]::WriteAllText((Join-Path $PSScriptRoot ($runId+'.meta.json')),$serialized)
52: [ordered]@{RunId=$runId;ExitCode=$process.ExitCode;OutputPath=$outPath} | ConvertTo-Json -Compress
