225:     public static void ValidateTodoStorage(IConfiguration configuration, string? instanceName)
226:     {
227:         ArgumentNullException.ThrowIfNull(configuration);
228: 
229:         var rawProvider = (GetEffectiveMcpValue(configuration, instanceName, "TodoStorage:Provider") ?? "database")
230:             .Trim();
231:         var provider = rawProvider.ToUpperInvariant();
232: 
233:         if (provider == "SQLITE")
234:         {
235:             System.Diagnostics.Trace.TraceWarning(
236:                 "Mcp:TodoStorage:Provider='sqlite' is deprecated; treating as 'database' (TODO storage now follows Mcp:Database:Provider).");
237:             provider = "DATABASE";
238:         }
239: 
240:         if (provider == "YAML")
241:             throw new InvalidOperationException(
242:                 "Mcp:TodoStorage:Provider='yaml' has been removed; the database is the sole source of truth and " +
243:                 "TODO.yaml is a read-only projection. Set Mcp:TodoStorage:Provider='database' and configure " +
244:                 "Mcp:Database:Provider (TR-MCP-CFG-007).");
245: 
246:         if (provider != "DATABASE")
247:             throw new InvalidOperationException(
248:                 $"Unsupported TODO storage provider '{rawProvider}'. Allowed value: database (legacy alias: sqlite).");
249: 
250:         if (provider == "DATABASE")
251:         {
252:             var dbProvider = GetEffectiveMcpValue(configuration, instanceName, "Database:Provider");
253:             if (string.IsNullOrWhiteSpace(dbProvider))
254:                 throw new InvalidOperationException(
255:                     "Mcp:Database:Provider is required when Mcp:TodoStorage:Provider is 'database'. " +
256:                     "Set it to one of: sqlite, sqlserver, postgresql (TR-MCP-CFG-007).");
257:         }
258:     }
