299:     {
300:         if (args is null || args.Length == 0)
301:             return null;
302: 
303:         var prefix = $"--{key}=";
304:         for (var i = 0; i < args.Length; i++)
305:         {
306:             var arg = args[i];
307:             if (arg.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
308:                 return arg.Substring(prefix.Length);
309: 
310:             if (string.Equals(arg, $"--{key}", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
311:                 return args[i + 1];
312:         }
313: 
314:         return null;
315:     }
316: }
