6: /// <summary>
7: /// TR-MCP-QBRAIN-005: Projects QBrainAi and Mcp keys onto Mcp using layer precedence.
8: /// Command line wins over environment, which wins over file QBrainAi, which wins over file Mcp.
9: /// Values are computed from the live provider list so reload and later test overrides stay current.
10: /// </summary>
11: internal sealed class CanonicalSectionProjectionSource : IConfigurationSource
12: {
13:     private readonly IConfigurationRoot _root;
14: 
15:     /// <summary>Creates a source bound to the configuration root that owns the other providers.</summary>
16:     public CanonicalSectionProjectionSource(IConfigurationRoot root)
17:     {
18:         ArgumentNullException.ThrowIfNull(root);
19:         _root = root;
20:     }
21: 
22:     /// <inheritdoc />
23:     public IConfigurationProvider Build(IConfigurationBuilder builder)
24:         => new CanonicalSectionProjectionProvider(_root);
25: }
26: 
27: /// <summary>
28: /// TR-MCP-QBRAIN-005: Last-added view of the effective Mcp section.
29: /// Within one layer, QBrainAi beats Mcp. A higher layer of either prefix beats a lower layer.
30: /// </summary>
31: internal sealed class CanonicalSectionProjectionProvider : ConfigurationProvider, IDisposable
32: {
33:     private const string CanonicalPrefix = "QBrainAi:";
34:     private const string LegacyPrefix = "Mcp:";
35:     private readonly IConfigurationRoot _root;
36:     private readonly object _gate = new();
37:     private readonly List<IDisposable> _subscriptions = [];
38:     private readonly List<IChangeToken> _watchedTokens = [];
39:     private Dictionary<string, string?>? _cache;
40:     private int _watchedProviderCount;
41:     private bool _subscribed;
42: 
43:     /// <summary>Creates a provider that reads sibling sources from <paramref name="root"/>.</summary>
44:     public CanonicalSectionProjectionProvider(IConfigurationRoot root)
45:     {
46:         ArgumentNullException.ThrowIfNull(root);
47:         _root = root;
48:     }
49: 
50:     /// <inheritdoc />
51:     public override void Load()
52:     {
53:         EnsureSubscriptions();
54:     }
55: 
56:     /// <inheritdoc />
57:     public override bool TryGet(string key, out string? value)
58:     {
59:         return CurrentMap().TryGetValue(key, out value);
60:     }
61: 
62:     /// <inheritdoc />
63:     public override IEnumerable<string> GetChildKeys(IEnumerable<string> earlierKeys, string? parentPath)
64:     {
65:         var prefix = parentPath is null ? string.Empty : parentPath + ConfigurationPath.KeyDelimiter;
66:         return CurrentMap()
67:             .Where(pair => pair.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
68:             .Select(pair => Segment(pair.Key, prefix))
69:             .Concat(earlierKeys)
70:             .OrderBy(key => key, ConfigurationKeyComparer.Instance);
71:     }
72: 
73:     /// <summary>Reads one projected Mcp suffix, ignoring values contributed by raw QBrainAi providers.</summary>
74:     public bool TryGetProjected(string suffix, out string? value)
75:     {
76:         ArgumentNullException.ThrowIfNull(suffix);
77:         return CurrentMap().TryGetValue(LegacyPrefix + suffix, out value);
78:     }
79: 
80:     /// <summary>Returns the effective product section (Mcp prefix removed) from the current projection.</summary>
81:     public IConfiguration CreateProductConfiguration()
82:     {
83:         var product = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
84:         foreach (var pair in CurrentMap())
85:         {
86:             if (pair.Key.StartsWith(LegacyPrefix, StringComparison.OrdinalIgnoreCase))
87:                 product[pair.Key[LegacyPrefix.Length..]] = pair.Value;
88:         }
89: 
90:         return new ConfigurationBuilder().AddInMemoryCollection(product).Build();
91:     }
92: 
93:     /// <inheritdoc />
94:     public void Dispose()
95:     {
96:         lock (_gate)
97:         {
98:             foreach (var subscription in _subscriptions)
99:                 subscription.Dispose();
100:             _subscriptions.Clear();
101:             _subscribed = false;
102:         }
103:     }
104: 
105:     private Dictionary<string, string?> CurrentMap()
106:     {
107:         lock (_gate)
108:         {
109:             return CurrentMapCore();
110:         }
111:     }
112: 
113:     private Dictionary<string, string?> CurrentMapCore()
114:     {
115:         var providerCount = 0;
116:         foreach (var provider in _root.Providers)
117:             providerCount++;
118:         if (_cache is not null
119:             && providerCount == _watchedProviderCount
120:             && _watchedTokens.TrueForAll(token => !token.HasChanged))
121:             return _cache;
122: 
123:         var providers = new List<FlattenedProvider>();
124:         var ordered = _root.Providers.ToList();
125:         var selfIndex = -1;
126:         for (var index = 0; index < ordered.Count; index++)
127:         {
128:             if (ReferenceEquals(ordered[index], this))
129:             {
130:                 selfIndex = index;
131:                 break;
132:             }
133:         }
134: 
135:         var seen = new HashSet<IConfigurationProvider>(ReferenceEqualityComparer.Instance);
136:         for (var index = 0; index < ordered.Count; index++)
137:         {
138:             if (index == selfIndex)
139:                 continue;
140:             foreach (var provider in Flatten(ordered[index], seen))
141:             {
142:                 providers.Add(new FlattenedProvider(provider, Classify(provider), selfIndex >= 0 && index > selfIndex, index));
143:             }
144:         }
145: 
146:         var result = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
147:         foreach (var batch in BuildBatches(providers))
148:             Overlay(result, batch);
149: 
150:         _watchedTokens.Clear();
151:         foreach (var provider in _root.Providers)
152:         {
153:             if (!ReferenceEquals(provider, this))
154:                 _watchedTokens.Add(provider.GetReloadToken());
155:         }
156: 
157:         _watchedProviderCount = providerCount;
158:         _cache = result;
159:         return result;
160:     }
161: 
162:     private void EnsureSubscriptions()
163:     {
164:         lock (_gate)
165:         {
166:             if (_subscribed)
167:                 return;
168:             _subscribed = true;
169:             foreach (var provider in _root.Providers)
170:             {
171:                 if (ReferenceEquals(provider, this) || provider is CanonicalSectionProjectionProvider)
172:                     continue;
173:                 var captured = provider;
174:                 _subscriptions.Add(ChangeToken.OnChange(captured.GetReloadToken, OnReload));
175:             }
176:         }
177:     }
178: 
179:     private static IEnumerable<ProviderBatch> BuildBatches(List<FlattenedProvider> providers)
180:     {
181:         foreach (var layer in new[] { SourceLayer.File, SourceLayer.Memory, SourceLayer.Environment, SourceLayer.CommandLine })
182:         {
183:             var before = providers.Where(item => !item.AfterProjection && item.Layer == layer).Select(item => item.Provider).ToList();
184:             if (before.Count > 0)
185:                 yield return new ProviderBatch(before, CanonicalBeatsLegacy: true, ReplaceWorkspaces: layer == SourceLayer.File);
186:         }
187: 
188:         var afterGroups = providers
189:             .Where(item => item.AfterProjection)
190:             .GroupBy(item => item.Order)
191:             .OrderBy(group => group.Key);
192:         foreach (var group in afterGroups)
193:         {
194:             yield return new ProviderBatch(group.Select(item => item.Provider).ToList(), CanonicalBeatsLegacy: true, ReplaceWorkspaces: false);
195:         }
196:     }
197: 
198:     private static void Overlay(Dictionary<string, string?> result, ProviderBatch batch)
199:     {
200:         var canonical = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
201:         var legacy = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
202:         foreach (var provider in batch.Providers)
203:         {
204:             foreach (var path in EnumeratePaths(provider))
205:             {
206:                 if (!provider.TryGet(path, out var value))
207:                     continue;
208:                 if (!TrySplit(path, out var isCanonical, out var suffix))
209:                     continue;
210:                 (isCanonical ? canonical : legacy)[suffix] = value;
211:             }
212:         }
213: 
214:         var canonicalWorkspaces = canonical.Where(pair => IsWorkspaceSuffix(pair.Key)).ToList();
215:         var legacyWorkspaces = legacy.Where(pair => IsWorkspaceSuffix(pair.Key)).ToList();
216:         if (batch.ReplaceWorkspaces && canonicalWorkspaces.Count > 0)
217:         {
218:             RemoveWorkspaceKeys(result);
219:             foreach (var pair in canonicalWorkspaces)
220:                 result[LegacyPrefix + pair.Key] = pair.Value;
221:         }
222:         else if (canonicalWorkspaces.Count > 0 || legacyWorkspaces.Count > 0)
223:         {
224:             var owned = ArrayParents(canonicalWorkspaces.Select(pair => pair.Key));
225:             foreach (var pair in legacyWorkspaces)
226:             {
227:                 if (batch.CanonicalBeatsLegacy && IsUnderOwnedArray(pair.Key, owned))
228:                     continue;
229:                 result[LegacyPrefix + pair.Key] = pair.Value;
230:             }
231: 
232:             if (batch.CanonicalBeatsLegacy)
233:             {
234:                 foreach (var pair in canonicalWorkspaces)
235:                     result[LegacyPrefix + pair.Key] = pair.Value;
236:             }
237:         }
238: 
239:         foreach (var pair in legacy)
240:         {
241:             if (IsWorkspaceSuffix(pair.Key))
242:                 continue;
243:             if (batch.CanonicalBeatsLegacy && canonical.ContainsKey(pair.Key))
244:                 continue;
245:             result[LegacyPrefix + pair.Key] = pair.Value;
246:         }
247: 
248:         if (batch.CanonicalBeatsLegacy)
249:         {
250:             foreach (var pair in canonical)
251:             {
252:                 if (IsWorkspaceSuffix(pair.Key))
253:                     continue;
254:                 result[LegacyPrefix + pair.Key] = pair.Value;
255:             }
256:         }
257:     }
258: 
259:     private static IEnumerable<IConfigurationProvider> Flatten(IConfigurationProvider provider, HashSet<IConfigurationProvider> seen)
260:     {
261:         if (!seen.Add(provider) || provider is CanonicalSectionProjectionProvider)
262:             yield break;
263: 
264:         var type = provider.GetType();
265:         if (type.Name.Contains("Chained", StringComparison.Ordinal))
266:         {
267:             var configuration = type.GetProperty("Configuration")?.GetValue(provider) as IConfigurationRoot;
268:             if (configuration is not null)
269:             {
270:                 foreach (var inner in configuration.Providers)
271:                 {
272:                     foreach (var flattened in Flatten(inner, seen))
273:                         yield return flattened;
274:                 }
275: 
276:                 yield break;
277:             }
278:         }
279: 
280:         yield return provider;
281:     }
282: 
283:     private static SourceLayer Classify(IConfigurationProvider provider)
284:     {
285:         var name = provider.GetType().Name;
286:         if (name.Contains("CommandLine", StringComparison.Ordinal))
287:             return SourceLayer.CommandLine;
288:         if (name.Contains("Environment", StringComparison.Ordinal))
289:             return SourceLayer.Environment;
290:         if (name.Contains("Memory", StringComparison.Ordinal))
291:             return SourceLayer.Memory;
292:         return SourceLayer.File;
293:     }
294: 
295:     private static IEnumerable<string> EnumeratePaths(IConfigurationProvider provider)
296:     {
297:         var keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
298:         Collect(provider, parent: null, keys);
299:         return keys;
300:     }
301: 
302:     private static void Collect(IConfigurationProvider provider, string? parent, ISet<string> keys)
303:     {
304:         foreach (var child in provider.GetChildKeys(Enumerable.Empty<string>(), parent))
305:         {
306:             var path = string.IsNullOrEmpty(parent) ? child : parent + ConfigurationPath.KeyDelimiter + child;
307:             if (!keys.Add(path))
308:                 continue;
309:             Collect(provider, path, keys);
310:         }
311:     }
312: 
313:     private static bool TrySplit(string path, out bool canonical, out string suffix)
314:     {
315:         if (path.StartsWith(CanonicalPrefix, StringComparison.OrdinalIgnoreCase))
316:         {
317:             canonical = true;
318:             suffix = path[CanonicalPrefix.Length..];
319:             return suffix.Length > 0;
320:         }
321: 
322:         if (path.StartsWith(LegacyPrefix, StringComparison.OrdinalIgnoreCase))
323:         {
324:             canonical = false;
325:             suffix = path[LegacyPrefix.Length..];
326:             return suffix.Length > 0;
327:         }
328: 
329:         canonical = false;
330:         suffix = string.Empty;
331:         return false;
332:     }
333: 
334:     private static bool IsWorkspaceSuffix(string suffix)
335:         => suffix.Equals("Workspaces", StringComparison.OrdinalIgnoreCase)
336:            || suffix.StartsWith("Workspaces:", StringComparison.OrdinalIgnoreCase);
337: 
338:     private static void RemoveWorkspaceKeys(Dictionary<string, string?> result)
339:     {
340:         foreach (var key in result.Keys.Where(IsWorkspaceResultKey).ToList())
341:             result.Remove(key);
342:     }
343: 
344:     private static bool IsWorkspaceResultKey(string key)
345:         => key.Equals("Mcp:Workspaces", StringComparison.OrdinalIgnoreCase)
346:            || key.StartsWith("Mcp:Workspaces:", StringComparison.OrdinalIgnoreCase);
347: 
348:     private static HashSet<string> ArrayParents(IEnumerable<string> suffixes)
349:     {
350:         var parents = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
351:         foreach (var suffix in suffixes)
352:         {
353:             var parts = suffix.Split(':');
354:             for (var index = 0; index < parts.Length; index++)
355:             {
356:                 if (!int.TryParse(parts[index], NumberStyles.None, CultureInfo.InvariantCulture, out _))
357:                     continue;
358:                 parents.Add(string.Join(':', parts.Take(index)));
359:             }
360:         }
361: 
362:         return parents;
363:     }
364: 
365:     private static bool IsUnderOwnedArray(string suffix, HashSet<string> parents)
366:     {
367:         var parts = suffix.Split(':');
368:         for (var index = 0; index < parts.Length; index++)
369:         {
370:             if (!int.TryParse(parts[index], NumberStyles.None, CultureInfo.InvariantCulture, out _))
371:                 continue;
372:             if (parents.Contains(string.Join(':', parts.Take(index))))
373:                 return true;
374:         }
375: 
376:         return false;
377:     }
378: 
379:     private static string Segment(string key, string prefix)
380:     {
381:         var index = key.IndexOf(ConfigurationPath.KeyDelimiter, prefix.Length, StringComparison.OrdinalIgnoreCase);
382:         return index < 0 ? key[prefix.Length..] : key[prefix.Length..index];
383:     }
384: 
385:     private enum SourceLayer
386:     {
387:         File = 1,
388:         Memory = 2,
389:         Environment = 3,
390:         CommandLine = 4,
391:     }
392: 
393:     private readonly record struct FlattenedProvider(IConfigurationProvider Provider, SourceLayer Layer, bool AfterProjection, int Order);
394: 
395:     private readonly record struct ProviderBatch(IReadOnlyList<IConfigurationProvider> Providers, bool CanonicalBeatsLegacy, bool ReplaceWorkspaces);
396: }
