2: [CmdletBinding()]
3: param([ValidateSet('Secrets','Chronology','Stores','Advisories')][string]$Mode)
4: $ErrorActionPreference='Stop'
5: switch($Mode){
6:  'Secrets'{
7:     $secrets=[Collections.Generic.HashSet[string]]::new()
8:     foreach($line in [IO.File]::ReadAllLines('/home/sharpninja/github/McpServer/AGENTS-README-FIRST.yaml')){
9:         $match=[regex]::Match($line,'^\s*["'']?(?<name>[A-Za-z0-9_\-]*?(?:api[_-]?key|token|secret)[A-Za-z0-9_\-]*)["'']?\s*:\s*["'']?(?<value>[^"''\s#]{20,})','IgnoreCase')
10:         if($match.Success){[void]$secrets.Add($match.Groups['value'].Value)}
11:     }
12:     $pattern=[regex]::new('(?<lead>(?:apiKey|api_key|X-Api-Key)\\?"?\s*[:=]\s*\\?"?)(?<value>[A-Za-z0-9_\-\.+/=]{20,})','IgnoreCase')
13:     $commits=@(& git log --first-parent --format=%H '3da2db93..780b6513')
14:     $checks=@(foreach($commit in $commits){
15:         $content=(& git show --format=fuller --no-ext-diff --no-renames $commit)-join "`n"
16:         if($LASTEXITCODE -ne 0){throw 'Commit read failed'}
17:         $literal=0
18:         foreach($secret in $secrets){$literal+=[regex]::Matches($content,[regex]::Escape($secret)).Count}
19:         [pscustomobject]@{Commit=$commit;CurrentMarkerMatches=$literal;ApiKeyPatternMatches=$pattern.Matches($content).Count}
20:     })
21:     $receiptChecks=@(foreach($file in Get-ChildItem $PSScriptRoot -File -Filter '*ug-r5*'){
22:         if($file.Extension -eq '.ps1'){continue}
23:         $content=Get-Content -LiteralPath $file.FullName -Raw
24:         if($null -eq $content){continue}
25:         $literal=0
26:         foreach($secret in $secrets){$literal+=[regex]::Matches($content,[regex]::Escape($secret)).Count}
27:         [pscustomobject]@{File=$file.Name;CurrentMarkerMatches=$literal;ApiKeyPatternMatches=$pattern.Matches($content).Count}
28:     })
